import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.realtime.translations.clientSecrets.create({ session: { model: "string", audio: { input: { transcription: { model: "string" }, noise_reduction: { type: "near_field" } }, output: { language: "string" } } }, expires_after: { anchor: "created_at", seconds: 600 } });
console.log(result);
